ALTER TABLE public.intranet_campaigns ADD COLUMN clicks bigint NOT NULL DEFAULT 0;
CREATE OR REPLACE FUNCTION public.intranet_open_campaign(p_id uuid) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE destination_url text; BEGIN UPDATE public.intranet_campaigns SET clicks=clicks+1 WHERE id=p_id AND status='ativa' RETURNING destination INTO destination_url; RETURN destination_url; END $$;
REVOKE ALL ON FUNCTION public.intranet_open_campaign(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.intranet_open_campaign(uuid) TO anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.is_admin_or_master(p_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p_user_id IS NOT NULL AND (EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=p_user_id AND role::text IN ('master','senior')) OR (EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=p_user_id AND role::text='admin') AND NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=p_user_id AND role::text IN ('financeiro','comercial','marketing','administracao','desenvolvimento')))); $$;
CREATE OR REPLACE FUNCTION public.can_read_finance(p_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p_user IS NOT NULL AND (EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=p_user AND role::text IN ('master','senior','financeiro')) OR (EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=p_user AND role::text='admin') AND NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=p_user AND role::text IN ('comercial','marketing','administracao','desenvolvimento')))); $$;
CREATE OR REPLACE FUNCTION public.intranet_can_access(p_sector text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND p_sector IN ('comercial','marketing','administracao','financeiro','desenvolvimento') AND (EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role::text IN ('master','senior')) OR p_sector=(SELECT role::text FROM public.user_roles WHERE user_id=auth.uid() AND role::text IN ('comercial','marketing','administracao','financeiro') ORDER BY CASE role::text WHEN 'comercial' THEN 1 WHEN 'marketing' THEN 2 WHEN 'administracao' THEN 3 ELSE 4 END LIMIT 1) OR (p_sector='desenvolvimento' AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role::text='desenvolvimento') AND NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role::text IN ('comercial','marketing','administracao','financeiro'))) OR (p_sector='administracao' AND public.is_admin_or_master(auth.uid()))); $$;
CREATE OR REPLACE FUNCTION public.intranet_health_probe() RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.intranet_can_access('desenvolvimento') THEN RAISE EXCEPTION 'Sem acesso a monitoramento' USING ERRCODE='42501'; END IF; RETURN true; END $$;
REVOKE ALL ON FUNCTION public.intranet_health_probe() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.intranet_health_probe() TO authenticated,service_role;